<template><view v-if="total>pageSize" class="pagination"><text class="summary">共 {{ total }} 条</text><view class="pager"><button :disabled="page<=1" @click="$emit('change',page-1)">上一页</button><text>{{ page }} / {{ pageCount }}</text><button :disabled="page>=pageCount" @click="$emit('change',page+1)">下一页</button></view></view></template>
<script setup>import{computed}from'vue';const props=defineProps({total:{type:Number,default:0},page:{type:Number,default:1},pageSize:{type:Number,default:10}});defineEmits(['change']);const pageCount=computed(()=>Math.max(1,Math.ceil(props.total/props.pageSize)));</script>
<style scoped>.pagination{margin-top:14px;display:flex;align-items:center;justify-content:space-between;color:var(--es-text-dim);font-size:12px}.pager{display:flex;align-items:center;gap:10px}.pager button{width:auto;margin:0;padding:6px 11px;color:var(--es-text);font-size:11px;line-height:1.3;background:#fff;border:1px solid var(--es-border-soft);border-radius:7px}.pager button[disabled]{color:var(--es-text-soft);background:#f9fafb}</style>
